16	func (s *APIV1Service) listUsersByID(ctx context.Context, userIDs []int32) (map[int32]*store.User, error) {
17		if len(userIDs) == 0 {
18			return map[int32]*store.User{}, nil
19		}
20	
21		uniqueUserIDs := make([]int32, 0, len(userIDs))
22		seenUserIDs := make(map[int32]struct{}, len(userIDs))
23		for _, userID := range userIDs {
24			if _, seen := seenUserIDs[userID]; seen {
25				continue
26			}
27			seenUserIDs[userID] = struct{}{}
28			uniqueUserIDs = append(uniqueUserIDs, userID)
29		}
30	
31		users, err := s.Store.ListUsers(ctx, &store.FindUser{IDList: uniqueUserIDs})
32		if err != nil {
33			return nil, err
34		}
35	
36		usersByID := make(map[int32]*store.User, len(users))
37		for _, user := range users {
38			usersByID[user.ID] = user
39		}
40		return usersByID, nil
41	}
