56	func (s *APIV1Service) ListAllUserStats(ctx context.Context, request *v1pb.ListAllUserStatsRequest) (*v1pb.ListAllUserStatsResponse, error) {
57		rowStatus := convertStateToStore(request.State)
58		memoFind := &store.FindMemo{
59			// Exclude comments by default.
60			ExcludeComments: true,
61			ExcludeContent:  true,
62			RowStatus:       &rowStatus,
63		}
64	
65		currentUser, err := s.fetchCurrentUser(ctx)
66		if err != nil {
67			return nil, status.Errorf(codes.Internal, "failed to get user: %v", err)
68		}
69	
70		if request.Filter != "" {
71			if err := s.validateFilter(ctx, request.Filter); err != nil {
72				return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
73			}
74			memoFind.Filters = append(memoFind.Filters, request.Filter)
75		}
76	
77		if request.State == v1pb.State_ARCHIVED {
78			// Archived memos are only visible to their creator.
79			if currentUser == nil {
80				return &v1pb.ListAllUserStatsResponse{}, nil
81			}
82			memoFind.CreatorID = &currentUser.ID
83		} else if currentUser == nil {
84			memoFind.VisibilityList = []store.Visibility{store.Public}
85		} else {
86			if memoFind.CreatorID == nil {
87				filter := fmt.Sprintf(`creator_id == %d || visibility in ["PUBLIC", "PROTECTED"]`, currentUser.ID)
88				memoFind.Filters = append(memoFind.Filters, filter)
89			} else if *memoFind.CreatorID != currentUser.ID {
90				memoFind.VisibilityList = []store.Visibility{store.Public, store.Protected}
91			}
92		}
93	
94		userMemoStatMap := make(map[int32]*v1pb.UserStats)
95		pinnedMemoIDsByUserID := make(map[int32][]int32)
96		limit := 1000
97		offset := 0
98		memoFind.Limit = &limit
99		memoFind.Offset = &offset
100	
101		for {
102			memos, err := s.Store.ListMemos(ctx, memoFind)
103			if err != nil {
104				return nil, status.Errorf(codes.Internal, "failed to list memos: %v", err)
105			}
106			if len(memos) == 0 {
107				break
108			}
109	
110			for _, memo := range memos {
111				// Initialize user stats if not exists
112				if _, exists := userMemoStatMap[memo.CreatorID]; !exists {
113					userMemoStatMap[memo.CreatorID] = &v1pb.UserStats{
114						Name:                  "",
115						TagCount:              make(map[string]int32),
116						MemoCreatedTimestamps: []*timestamppb.Timestamp{},
117						MemoUpdatedTimestamps: []*timestamppb.Timestamp{},
118						PinnedMemos:           []string{},
119						MemoTypeStats: &v1pb.UserStats_MemoTypeStats{
120							LinkCount: 0,
121							CodeCount: 0,
122							TodoCount: 0,
123							UndoCount: 0,
124						},
125					}
126				}
127	
128				stats := userMemoStatMap[memo.CreatorID]
129	
130				stats.MemoCreatedTimestamps = append(stats.MemoCreatedTimestamps, timestamppb.New(time.Unix(memo.CreatedTs, 0)))
131				stats.MemoUpdatedTimestamps = append(stats.MemoUpdatedTimestamps, timestamppb.New(time.Unix(memo.UpdatedTs, 0)))
132	
133				// Count memo stats
134				stats.TotalMemoCount++
135	
136				// Count tags and other properties
137				if memo.Payload != nil {
138					for _, tag := range memo.Payload.Tags {
139						stats.TagCount[tag]++
140					}
141					if memo.Payload.Property != nil {
142						if memo.Payload.Property.HasLink {
143							stats.MemoTypeStats.LinkCount++
144						}
145						if memo.Payload.Property.HasCode {
146							stats.MemoTypeStats.CodeCount++
147						}
148						if memo.Payload.Property.HasTaskList {
149							stats.MemoTypeStats.TodoCount++
150						}
151						if memo.Payload.Property.HasIncompleteTasks {
152							stats.MemoTypeStats.UndoCount++
153						}
154					}
155				}
156	
157				// Track pinned memos
158				if memo.Pinned {
159					pinnedMemoIDsByUserID[memo.CreatorID] = append(pinnedMemoIDsByUserID[memo.CreatorID], memo.ID)
160				}
161			}
162	
163			offset += limit
164		}
165	
166		userMemoStats := []*v1pb.UserStats{}
167		userIDs := make([]int32, 0, len(userMemoStatMap))
168		for userID := range userMemoStatMap {
169			userIDs = append(userIDs, userID)
170		}
171		usernamesByID, err := s.listUsernamesByID(ctx, userIDs)
172		if err != nil {
173			return nil, status.Errorf(codes.Internal, "failed to list users: %v", err)
174		}
175		for userID, userMemoStat := range userMemoStatMap {
176			username, ok := usernamesByID[userID]
177			if !ok {
178				return nil, status.Errorf(codes.Internal, "failed to resolve user stats name")
179			}
180			userMemoStat.Name = fmt.Sprintf("%s/stats", BuildUserName(username))
181			for _, memoID := range pinnedMemoIDsByUserID[userID] {
182				userMemoStat.PinnedMemos = append(userMemoStat.PinnedMemos, fmt.Sprintf("%s/memos/%d", BuildUserName(username), memoID))
183			}
184			userMemoStats = append(userMemoStats, userMemoStat)
185		}
186	
187		response := &v1pb.ListAllUserStatsResponse{
188			Stats: userMemoStats,
189		}
190		return response, nil
191	}
