137	func (d *DB) DeleteMemoRelation(ctx context.Context, delete *store.DeleteMemoRelation) error {
138		where, args := []string{"TRUE"}, []any{}
139		if delete.MemoID != nil {
140			where, args = append(where, "memo_id = ?"), append(args, *delete.MemoID)
141		}
142		if delete.RelatedMemoID != nil {
143			where, args = append(where, "related_memo_id = ?"), append(args, *delete.RelatedMemoID)
144		}
145		if delete.Type != nil {
146			where, args = append(where, "type = ?"), append(args, *delete.Type)
147		}
148		stmt := `
149			DELETE FROM memo_relation
150			WHERE ` + strings.Join(where, " AND ")
151		result, err := d.db.ExecContext(ctx, stmt, args...)
152		if err != nil {
153			return err
154		}
155		if _, err = result.RowsAffected(); err != nil {
156			return err
157		}
158		return nil
